declarations.moonbit_signature:
///|
#borrow(path)
pub extern "C" fn abi_path_length(path : Bytes) -> Int = "abi_path_length"

///|
#borrow(mbg_status)
extern "C" fn mbg_bridge_abi_scalar_out(
  seed : Int,
  mbg_status : FixedArray[Int],
) -> Int = "mbg_bridge_abi_scalar_out"

///|
pub fn abi_scalar_out(seed : Int) -> (Int, Int) {
  let mbg_status = FixedArray::make(1, 0)
  let value = mbg_bridge_abi_scalar_out(seed, mbg_status)
  (mbg_status[0], value)
}

///|
#borrow(mbg_status)
extern "C" fn mbg_bridge_abi_handle_out(
  seed : Int,
  mbg_status : FixedArray[Int],
) -> C_abi_handle = "mbg_bridge_abi_handle_out"

///|
pub fn abi_handle_out(seed : Int) -> (Int, C_abi_handle) {
  let mbg_status = FixedArray::make(1, 0)
  let value = mbg_bridge_abi_handle_out(seed, mbg_status)
  (mbg_status[0], value)
}

///|
#borrow(mbg_absent)
extern "C" fn mbg_bridge_abi_borrowed_text(
  mode : Int,
  mbg_absent : FixedArray[Int],
) -> Bytes = "mbg_bridge_abi_borrowed_text"

///|
pub fn abi_borrowed_text(mode : Int) -> String? raise {
  let mbg_absent = FixedArray::make(1, 0)
  let bytes = mbg_bridge_abi_borrowed_text(mode, mbg_absent)
  if mbg_absent[0] == 1 {
    None
  } else if mbg_absent[0] == 2 {
    fail("returned C string is too large")
  } else {
    Some(@utf8.decode(bytes))
  }
}

